use std::fmt;

/// Represents errors that can occur during configuration parsing.
#[derive(Debug)]
pub enum ConfigParseError {
    /// Returned when a non-comment, non-blank line does not contain an '=' character.
    MissingDelimiter(String),
}

impl fmt::Display for ConfigParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ConfigParseError::MissingDelimiter(line) => {
                write!(f, "Configuration line missing '=' delimiter: '{}'", line)
            }
        }
