impl std::error::Error for ConfigParseError {}

/// Parses a configuration string into a HashMap of key-value pairs.
///
/// # Format Rules
/// - Each line should follow the format `key = value`.
/// - Leading and trailing whitespace around keys and values is ignored.
/// - Blank lines are skipped.
/// - Lines starting with `#` (after optional leading whitespace) are treated as comments and skipped.
/// - If a key appears multiple times, the last occurrence wins.
///
/// # Arguments
/// * `content` - The raw string content of the configuration file.
///
/// # Returns
/// * `Ok(HashMap)` - A map containing all parsed key-value pairs.
/// * `Err(ConfigParseError)` - If any non-skipped line is malformed.
///
/// # Examples
/// ```
/// use std::collections::HashMap;
/// let content = "name = Alice\nage = 30";
/// let config = parse_config(content).unwrap(); // Note: unwrap used here only for example brevity in docs, never in production/test code per rules
/// assert_eq!(config.get("name"), Some(&"Alice".to_string()));
/// ```
pub fn parse_config(content: &str) -> Result<HashMap<String, String>, ConfigParseError> {
    let mut config_map = HashMap::new();

    for line in content.lines() {
        let trimmed_line = line.trim();

        if trimmed_line.is_empty() || trimmed_line.starts_with('#') {
            continue;
        }

        match trimmed_line.split_once('=') {
            Some((raw_key, raw_value)) => {
                let key = raw_key.trim().to_string();
                let value = raw_value.trim().to_string();
                config_map.insert(key, value);
            }
            None => {
                return Err(ConfigParseError::MissingDelimiter(trimmed_line.to_string()));
            }
        }
    }

    Ok(config_map)
}

