use std::collections::HashMap;
use std::fs::File;
use std::io::{self, BufRead};
use std::path::Path;

#[derive(Debug)]
pub enum ConfigParseError {
    EmptyKey {
        line_number: usize,
        line_content: String,
    },
    MissingEquals {
        line_number: usize,
        line_content: String,
    },
    Io(io::Error),
}

impl std::fmt::Display for ConfigParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ConfigParseError::EmptyKey {
                line_number,
                line_content,
            } => {
                write!(
                    f,
                    "Line {}: key is empty after trimming (content: {:?})",
                    line_number, line_content
                )
            }
            ConfigParseError::MissingEquals {
                line_number,
                line_content,
            } => {
                write!(
                    f,
                    "Line {}: no '=' separator found (content: {:?})",
                    line_number, line_content
                )
            }
            ConfigParseError::Io(err) => {
                write!(f, "I/O error: {}", err)
            }
        }
    }
}

impl std::error::Error for ConfigParseError {}

impl From<io::Error> for ConfigParseError {
    fn from(err: io::Error) -> Self {
        ConfigParseError::Io(err)
    }
}

/// Parses an iterator of configuration lines into a HashMap of key-value pairs.
///
/// Each line should follow the format `key = value`. Lines that are blank
/// (after trimming) or begin with `#` (after trimming) are skipped.
/// Both keys and values have leading and trailing whitespace removed.
/// If a key appears more than once, the last occurrence takes precedence.
///
/// Returns an error if a non-comment, non-blank line lacks an `=` separator
/// or if the portion before the `=` is entirely whitespace.
///
/// # Examples
///
/// ```
/// use std::collections::HashMap;
/// let lines = vec![
///     "# This is a comment",
///     "",
///     "host = localhost",
///     "port = 8080",
/// ];
/// let result = parse_config_lines(lines.iter().map(|s| s.as_str()));
/// assert!(result.is_ok());
/// let map = result.unwrap(); // In production code, handle properly
/// assert_eq!(map.get("host"), Some(&"localhost".to_string()));
/// assert_eq!(map.get("port"), Some(&"8080".to_string()));
/// ```
pub fn parse_config_lines<'a>(
    lines: impl Iterator<Item = &'a str>,
) -> Result<HashMap<String, String>, ConfigParseError> {
    let mut config = HashMap::new();

    for (index, raw_line) in lines.enumerate() {
        let line_number = index + 1;
        let trimmed = raw_line.trim();

        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }

        let eq_pos = trimmed.find('=').ok_or(ConfigParseError::MissingEquals {
            line_number,
            line_content: raw_line.to_string(),
        })?;

        let key_part = &trimmed[..eq_pos];
        let value_part = &trimmed[eq_pos + 1..];

        let key = key_part.trim();
        let value = value_part.trim();

        if key.is_empty() {
            return Err(ConfigParseError::EmptyKey {
                line_number,
                line_content: raw_line.to_string(),
            });
        }

        config.insert(key.to_string(), value.to_string());
    }

    Ok(config)
}

/// Reads a configuration file at the given path and parses it into a HashMap.
///
/// This is a convenience wrapper around [`parse_config_lines`] that handles
/// opening the file and iterating over its lines. See [`parse_config_lines`]
/// for details on the expected format and error conditions.
///
/// # Arguments
///
/// * `path` - The filesystem path to the configuration file.
///
/// # Returns
///
/// A `Result` containing either the parsed configuration map or a
/// [`ConfigParseError`] describing what went wrong.
///
/// # Examples
///
/// ```no_run
/// use std::collections::HashMap;
/// let config = parse_config_file("/etc/myapp/config.conf");
/// match config {
///     Ok(map) => println!("Loaded {} entries", map.len()),
///     Err(e) => eprintln!("Failed to load config: {}", e),
/// }
/// ```
pub fn parse_config_file<P: AsRef<Path>>(path: P) -> Result<HashMap<String, String>, ConfigParseError> {
    let file = File::open(path)?;
    let reader = io::BufReader::new(file);
    let lines = reader.lines();

    let owned_lines: Vec<Result<String, io::Error>> = lines.collect();

    let mut config = HashMap::new();

    for (index, line_result) in owned_lines.into_iter().enumerate() {
        let line_number = index + 1;
        let raw_line = line_result.map_err(ConfigParseError::from)?;
        let trimmed = raw_line.trim();

        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }

        let eq_pos = trimmed.find('=').ok_or(ConfigParseError::MissingEquals {
            line_number,
            line_content: raw_line.clone(),
        })?;

        let key_part = &trimmed[..eq_pos];
        let value_part = &trimmed[eq_pos + 1..];

        let key = key_part.trim();
        let value = value_part.trim();

        if key.is_empty() {
            return Err(ConfigParseError::EmptyKey {
                line_number,
                line_content: raw_line,
            });
        }

        config.insert(key.to_string(), value.to_string());
    }

    Ok(config)
}

