use std::collections::HashMap;
use std::fs;
use std::io::{self, BufRead};
use std::path::Path;

#[derive(Debug)]
pub enum ConfigError {
    Io(io::Error),
    InvalidLine(String),
}

impl std::fmt::Display for ConfigError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ConfigError::Io(err) => write!(f, "IO error: {}", err),
            ConfigError::InvalidLine(line) => write!(f, "invalid config line: '{}'", line),
        }
    }
}

impl std::error::Error for ConfigError {}

impl From<io::Error> for ConfigError {
    fn from(err: io::Error) -> Self {
        ConfigError::Io(err)
    }
}

/// Parses a configuration file containing `key = value` pairs and `[section]` headers
/// into a HashMap.
///
/// Lines that are blank or begin with `#` (after optional leading whitespace)
/// are ignored. Each valid key-value line must contain exactly one `=` separator.
/// Leading and trailing whitespace around keys and values is stripped.
///
/// Section headers are denoted by `[section_name]`. Keys appearing after a section
/// header are prefixed with `section_name.` until the next section header or end of file.
/// Keys before any section header remain unprefixed.
///
/// Returns an error if the file cannot be read or if any line is malformed.
pub fn parse_config_file<P: AsRef<Path>>(path: P) -> Result<HashMap<String, String>, ConfigError> {
    let file = fs::File::open(path)?;
    let reader = io::BufReader::new(file);
    let mut config = HashMap::new();
    let mut current_section: Option<String> = None;

    for line_result in reader.lines() {
        let line = line_result?;
        let trimmed = line.trim();

        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }

        if trimmed.starts_with('[') && trimmed.ends_with(']') {
            let section_name = trimmed[1..trimmed.len() - 1].trim();
            if section_name.is_empty() {
                return Err(ConfigError::InvalidLine(trimmed.to_string()));
            }
            if section_name.contains('[') || section_name.contains(']') {
                return Err(ConfigError::InvalidLine(trimmed.to_string()));
            }
            current_section = Some(section_name.to_string());
            continue;
        }

        let parts: Vec<&str> = trimmed.splitn(2, '=').collect();
        if parts.len() != 2 {
            return Err(ConfigError::InvalidLine(trimmed.to_string()));
        }

        let raw_key = parts[0].trim();
        let value = parts[1].trim().to_string();

        if raw_key.is_empty() {
            return Err(ConfigError::InvalidLine(trimmed.to_string()));
        }

        let full_key = match &current_section {
            Some(section) => format!("{}.{}", section, raw_key),
            None => raw_key.to_string(),
        };

        config.insert(full_key, value);
    }

    Ok(config)
}

