## Full Updated Code

```rust
use std::collections::HashMap;
use std::fmt;

#[derive(Debug)]
pub enum ParseError {
    InvalidLine(String),
    InvalidSection(String),
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseError::InvalidLine(line) => {
                write!(f, "invalid config line: '{}'", line)
            }
            ParseError::InvalidSection(section) => {
                write!(f, "invalid section header: '{}'", section)
            }
        }
    }
}

impl std::error::Error for ParseError {}

pub fn parse_config(content: &str) -> Result<HashMap<String, String>, ParseError> {
    let mut config = HashMap::new();
    let mut current_section: Option<String> = None;

    for line in content.lines() {
        let trimmed = line.trim();

        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }

        if trimmed.starts_with('[') && trimmed.ends_with(']') {
            let inner = &trimmed[1..trimmed.len() - 1];
            let section_name = inner.trim();

            if section_name.is_empty() {
                return Err(ParseError::InvalidSection(trimmed.to_string()));
            }

            current_section = Some(section_name.to_string());
            continue;
        }

        let parts: Vec<&str> = trimmed.splitn(2, '=').collect();
        if parts.len() != 2 {
            return Err(ParseError::InvalidLine(trimmed.to_string()));
        }

        let raw_key = parts[0].trim();
        let value = parts[1].trim().to_string();

        if raw_key.is_empty() {
            return Err(ParseError::InvalidLine(trimmed.to_string()));
        }

        let final_key = match &current_section {
            Some(section) => format!("{}.{}", section, raw_key),
            None => raw_key.to_string(),
        };

        config.insert(final_key, value);
    }

    Ok(config)
}

