if let Some(comment_pos) = value_part.find("#") {
    // Only strip if '#' is preceded by whitespace or start of string to avoid breaking URLs
    if comment_pos == 0 || value_part.as_bytes()[comment_pos - 1].is_ascii_whitespace() {
         value = value_part[..comment_pos].trim().to_string();
    } else {
         value = value_part.to_string();
