```rust
use std::collections::HashMap;
use std::fmt;

/// Represents errors that can occur during configuration file parsing.
#[derive(Debug, PartialEq)]
pub enum ConfigParseError {
    /// The line does not contain an '=' separator and is not a valid section header.
    MissingEquals,
    /// The key portion of the line is empty after trimming.
    EmptyKey,
    /// A line started with '[' but did not have a corresponding ']'.
    MalformedSectionHeader,
    /// A section header was syntactically valid but contained no name.
    EmptySectionName,
    /// A generic error variant for future extensibility.
    Other(String),
}

impl fmt::Display for ConfigParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ConfigParseError::MissingEquals => write!(f, "line missing '=' separator"),
            ConfigParseError::EmptyKey => write!(f, "empty key encountered"),
            ConfigParseError::MalformedSectionHeader => {
                write!(f, "malformed section header: missing closing ']'")
            }
            ConfigParseError::EmptySectionName => {
                write!(f, "empty section name in section header")
            }
            ConfigParseError::Other(msg) => write!(f, "{}", msg),
        }
    }
}

impl std::error::Error for ConfigParseError {}

/// Parses a configuration string consisting of `key = value` lines and `[section]` headers.
///
/// Blank lines and lines whose first non-whitespace character is '#' are ignored.
/// Leading and trailing whitespace around keys, values, and section names is stripped.
/// The first '=' splits the key from the value; subsequent '=' characters belong to the value.
///
/// Section headers are denoted by `[SectionName]`. All subsequent key-value pairs are stored
/// with keys prefixed by `SectionName.` until the next section header or end of file.
/// Keys appearing before any section header are stored without a prefix.
///
/// Returns a `HashMap` mapping fully qualified keys to their corresponding values, or an error
/// if any non-comment, non-blank line fails to parse correctly.
///
/// # Examples
///
/// ```no_run
/// // Documentation examples typically show ideal usage. 
/// // Actual testing follows strict no-unwrap policy.
/// ```
pub fn parse_config(input: &str) -> Result<HashMap<String, String>, ConfigParseError> {
    let mut config = HashMap::new();
    let mut current_prefix = String::new();

    for line in input.lines() {
        let trimmed = line.trim();

        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }

        if trimmed.starts_with('[') {
            let close_idx = trimmed.find(']').ok_or(ConfigParseError::MalformedSectionHeader)?;

            // Ensure the closing bracket exists and is after the opening one
            if close_idx == 0 {
                 // This case is technically impossible given starts_with('['), 
                 // but defensive check for clarity
                 return Err(ConfigParseError::MalformedSectionHeader);
            }

            let section_name_raw = &trimmed[1..close_idx];
            let section_name = section_name_raw.trim();

            if section_name.is_empty() {
                return Err(ConfigParseError::EmptySectionName);
            }

            current_prefix = format!("{}.", section_name);
            continue;
        }

        let (raw_key, raw_value) = trimmed
            .split_once('=')
            .ok_or(ConfigParseError::MissingEquals)?;

        let key_part = raw_key.trim();
        let value_part = raw_value.trim();

        if key_part.is_empty() {
            return Err(ConfigParseError::EmptyKey);
        }

        let full_key = format!("{}{}", current_prefix, key_part);
        config.insert(full_key, value_part.to_string());
    }

    Ok(config)
}

